<?php require 'config.php';require_admin();verify_csrf();$s=read_json('settings.json',[]);if($_SERVER['REQUEST_METHOD']==='POST'){foreach(['store_name','phone1','phone2','whatsapp','facebook','telegram','tiktok','x'] as $k)$s[$k]=trim($_POST[$k]??'');write_json('settings.json',$s);flash('تم حفظ الإعدادات.');redirect('settings.php');}$title='الإعدادات';require 'header.php';?><div class="form"><h1>⚙️ إعدادات المتجر</h1><form method="post"><input type="hidden" name="csrf" value="<?=csrf_token()?>"><?php foreach(['store_name'=>'اسم المتجر','phone1'=>'الهاتف الأول','phone2'=>'الهاتف الثاني','whatsapp'=>'واتساب','facebook'=>'فيسبوك','telegram'=>'Telegram','tiktok'=>'TikTok','x'=>'X'] as $k=>$label):?><label><?=$label?></label><input name="<?=$k?>" value="<?=e($s[$k]??'')?>"><?php endforeach;?><button class="btn">حفظ</button></form></div><?php require 'footer.php';?>